import{_ as s,o as a,c as t,a2 as i}from"./chunks/framework.BZO4qERu.js";const k=JSON.parse('{"title":"MCP","description":"","frontmatter":{},"headers":[],"relativePath":"zh/developers/mcp.md","filePath":"zh/developers/mcp.md","lastUpdated":1793111003000}'),d={name:"zh/developers/mcp.md"};function o(l,e,p,n,h,c){return a(),t("div",null,[...e[0]||(e[0]=[i(`<h1 id="mcp" tabindex="-1">MCP <a class="header-anchor" href="#mcp" aria-label="Permalink to &quot;MCP&quot;">​</a></h1><p>在支持 Model Context Protocol 的助手中调用 PaperSeek。本地 MCP 服务将社区版应用能力提供为结构化工具。</p><h2 id="安装匹配版本" tabindex="-1">安装匹配版本 <a class="header-anchor" href="#安装匹配版本" aria-label="Permalink to &quot;安装匹配版本&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pip</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;paperseek-mcp==1.0.0b5&quot;</span></span></code></pre></div><p>独立适配器依赖相同版本的 <code>paperseek</code>，复用社区版应用服务，不维护另一套检索引擎。</p><h2 id="使用-stdio" tabindex="-1">使用 stdio <a class="header-anchor" href="#使用-stdio" aria-label="Permalink to &quot;使用 stdio&quot;">​</a></h2><p>客户端配置示例：</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;mcpServers&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;paperseek&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;command&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;paperseek-mcp&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;args&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;--transport&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;stdio&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>确保客户端能够找到已安装的命令。通过客户端的环境或密钥配置提供模型与数据源凭据，不要公开包含真实 Key 的配置文件。</p><p>MCP 进程与 CLI 使用相同的 <code>PAPERSEEK_*</code> 环境变量。只在 Web 表单中填写的配置不会自动传给这个独立进程，它也不会自动加载 <code>.env</code>，详见<a href="./../reference/configuration">配置参考</a>。连接前可在相同环境运行 <code>paperseek doctor --json</code>，不需要启动 Web 服务或登录 PaperSeek 账户。</p><h2 id="可用工具" tabindex="-1">可用工具 <a class="header-anchor" href="#可用工具" aria-label="Permalink to &quot;可用工具&quot;">​</a></h2><table tabindex="0"><thead><tr><th>工具</th><th>用途</th></tr></thead><tbody><tr><td><code>list_sources</code> / <code>get_source_capabilities</code></td><td>查看数据源及其能力</td></tr><tr><td><code>start_search</code></td><td>开始持久化任务，立即返回任务 ID</td></tr><tr><td><code>get_search_status</code> / <code>get_search_events</code></td><td>查看状态与事件</td></tr><tr><td><code>get_search_results</code></td><td>分页读取结果</td></tr><tr><td><code>get_citation_graph</code></td><td>读取引用图谱</td></tr><tr><td><code>cancel_search</code></td><td>请求取消</td></tr><tr><td><code>export_results</code></td><td>导出完整结果，格式为 JSON、CSV、BibTeX 或 RIS</td></tr></tbody></table><p>连接会话不等于检索任务的生命周期。保存返回的 <code>run_id</code>，用它继续检查状态与读取结果；结果分页时跟随返回的游标，不要把第一页当成全部文献。</p><h2 id="一次检索的调用流程" tabindex="-1">一次检索的调用流程 <a class="header-anchor" href="#一次检索的调用流程" aria-label="Permalink to &quot;一次检索的调用流程&quot;">​</a></h2><ol><li>用 <code>list_sources</code> 和 <code>get_source_capabilities</code> 获取数据源与筛选项 ID。</li><li>调用 <code>start_search</code>，提供问题、数据源和预算（<code>fast</code>、<code>medium</code>、<code>high</code> 或 <code>max</code>），立即获得 <code>run_id</code> 和 <code>status</code>。重试提交时，复用非空的 <code>idempotency_key</code> 和相同参数，避免重复创建任务。</li><li>每隔几秒调用 <code>get_search_status</code>。<code>completed</code>、<code>completed_with_warnings</code>、<code>failed</code>、<code>cancelled</code> 表示任务已结束；事件页为空不代表完成。</li><li>用 <code>get_search_results</code> 读取结果，直到 <code>next_cursor</code> 为 <code>null</code>。事件和结果每页可取 1–200 项；完整的 JSON、CSV、BibTeX 或 RIS 使用 <code>export_results</code> 导出。</li></ol><p>检索期间应保持 MCP 进程运行，其内置 worker 才能推进任务。断开连接不会主动取消检索，需要停止时调用 <code>cancel_search</code>。任务保存在本地数据库中，重启后使用同一数据库即可继续读取。默认路径为 <code>~/.paperseek/paperseek.db</code>，可通过 <code>--database</code> 或 <code>PAPERSEEK_DATABASE</code> 修改。</p><p>工具同时返回结构化 JSON 和兼容的文本表示。参数或执行错误通过 MCP 的 <code>isError</code> 返回，未知工具名称作为协议错误返回。读取类工具标记为只读，开始与取消检索声明其副作用；检索可能产生所配置服务商的 API 费用。</p><h2 id="本地-http" tabindex="-1">本地 HTTP <a class="header-anchor" href="#本地-http" aria-label="Permalink to &quot;本地 HTTP&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">paperseek-mcp</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --transport</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> streamable-http</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --host</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 127.0.0.1</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --port</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 8766</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --path</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /mcp</span></span></code></pre></div><p>旧客户端仍可使用 <code>--transport sse-legacy</code>。新配置优先选择 stdio 或 Streamable HTTP。</p><p>非回环 HTTP 必须配置 <code>PAPERSEEK_MCP_SERVICE_TOKEN</code>、HTTPS 的 <code>PAPERSEEK_MCP_PUBLIC_URL</code>，以及明确的 <code>PAPERSEEK_MCP_ALLOWED_HOSTS</code> 和 <code>PAPERSEEK_MCP_ALLOWED_ORIGINS</code>。TLS 由反向代理终止，不要将未认证的本地服务直接开放到公网。</p><p>此 HTTP 入口用于私有社区版工作区。配置服务令牌后，客户端每个请求均须携带 <code>Authorization: Bearer &lt;token&gt;</code>。它不提供 OAuth 登录流程；只支持自动 OAuth 发现的客户端请改用 stdio。同一实例的客户端共享数据库和配置的模型凭据，因此它不是面向公众、按用户隔离的 BYOK 服务。</p><h2 id="协议与排查" tabindex="-1">协议与排查 <a class="header-anchor" href="#协议与排查" aria-label="Permalink to &quot;协议与排查&quot;">​</a></h2><p>适配器使用<a href="https://github.com/modelcontextprotocol/python-sdk" target="_blank" rel="noreferrer">官方 Python SDK</a>处理 MCP 服务发现、传输和结构化工具消息。当前提供 tools；resources 和 prompts 是可选能力，这条检索流程不需要为了形式完整而增加它们。旧 SSE 仅用于兼容。</p><p>客户端无法启动时，先尝试填写命令的绝对路径并检查环境变量；HTTP 连接失败时，检查令牌和 Host/Origin 白名单。诊断日志输出到 stderr，stdio 的 stdout 专用于 MCP 消息。内部异常只向客户端返回简短失败提示，具体原因查看服务端日志。</p><h2 id="agent-skill" tabindex="-1">Agent Skill <a class="header-anchor" href="#agent-skill" aria-label="Permalink to &quot;Agent Skill&quot;">​</a></h2><p>安装、首次使用与配置说明已独立到 <a href="./skill">Agent Skill 指南</a>。通过 Skill 使用 CLI 不需要安装 MCP。</p>`,27)])])}const E=s(d,[["render",o]]);export{k as __pageData,E as default};
